`timescale 1ns / 1ps

// tb_two_programs (Lane 1, 2026-11-07; brief v2 A5 "two different programs, and a pass rule that checks the values each one
// writes"): copy of tb_two_tiles (registered as i14_two_tiles, unchanged) with tile 1 running sw/riscv/memtest.S instead of
// hello_words. Checks (CHECKS = 9, frozen before the first run): the 8 tb_two_tiles checks + T2_TILE1_MEMTEST_VALUE (tile 1
// DMEM 0x4000 = 0x600D0011, the value memtest writes when its 17 tests pass).
module tb_two_programs;

    // Lane 1 2026-11-07: program image as a read-only include (generated by scripts/hex_to_svh.py from
    // sw/riscv/hello_words.hex), preloaded at time 0 instead of $readmemh("sw/hello_words.hex"): same words, same
    // addresses, no run-directory-relative path. Checks and counts unchanged.
    `include "hello_words.svh"
    `include "memtest.svh"
    initial for (int k = 0; k < HELLO_WORDS_N; k++) begin
        memory0.imem_inst.mem[k] = HELLO_WORDS[k];
    end
    initial for (int k = 0; k < MEMTEST_N; k++) memory1.imem_inst.mem[k] = MEMTEST[k];

    logic clk;
    logic reset;

    // ============================================================
    // TILE 0
    // ============================================================

    logic [3:0]  sw0;
    logic [3:0]  led0;
    logic        uart0;

    logic        imem_valid0;
    logic [31:0] imem_addr0;
    logic [31:0] imem_wdata0;
    logic [3:0]  imem_wstrb0;
    logic        imem_ready0;
    logic [31:0] imem_rdata0;

    logic        dmem_valid0;
    logic [31:0] dmem_addr0;
    logic [31:0] dmem_wdata0;
    logic [3:0]  dmem_wstrb0;
    logic        dmem_ready0;
    logic [31:0] dmem_rdata0;

    logic        tmem_req0;
    logic        tmem_we0;
    logic [31:0] tmem_addr0;
    logic [31:0] tmem_wdata0;
    logic [3:0]  tmem_wstrb0;
    logic        tmem_is_fetch0;
    logic        tmem_gnt0;
    logic        tmem_rvalid0;
    logic [31:0] tmem_rdata0;
    logic        tmem_err0;

    logic        attested0;
    logic        timeout0;
    logic        attest_req0;

    logic [31:0] pc0;
    logic [31:0] inst0;
    logic        valid0;
    logic        trap0;


    // ============================================================
    // TILE 1
    // ============================================================

    logic [3:0]  sw1;
    logic [3:0]  led1;
    logic        uart1;

    logic        imem_valid1;
    logic [31:0] imem_addr1;
    logic [31:0] imem_wdata1;
    logic [3:0]  imem_wstrb1;
    logic        imem_ready1;
    logic [31:0] imem_rdata1;

    logic        dmem_valid1;
    logic [31:0] dmem_addr1;
    logic [31:0] dmem_wdata1;
    logic [3:0]  dmem_wstrb1;
    logic        dmem_ready1;
    logic [31:0] dmem_rdata1;

    logic        tmem_req1;
    logic        tmem_we1;
    logic [31:0] tmem_addr1;
    logic [31:0] tmem_wdata1;
    logic [3:0]  tmem_wstrb1;
    logic        tmem_is_fetch1;
    logic        tmem_gnt1;
    logic        tmem_rvalid1;
    logic [31:0] tmem_rdata1;
    logic        tmem_err1;

    logic        attested1;
    logic        timeout1;
    logic        attest_req1;

    logic [31:0] pc1;
    logic [31:0] inst1;
    logic        valid1;
    logic        trap1;


    // ============================================================
    // CLOCK
    // ============================================================

    always #10 clk = ~clk;


    // ============================================================
    // TILE 0
    // ============================================================

    tile_top #(
        .TILE_ID    (4'h0),
        .BUILD_ID   (32'h0000_0001),
        .IMEM_WORDS (4096),
        .DMEM_WORDS (4096),
        .HAS_UART   (1'b1)
    ) tile0 (
        .clk_i   (clk),
        .reset_i (reset),

        .imem_valid_o (imem_valid0),
        .imem_addr_o  (imem_addr0),
        .imem_wdata_o (imem_wdata0),
        .imem_wstrb_o (imem_wstrb0),
        .imem_ready_i (imem_ready0),
        .imem_rdata_i (imem_rdata0),

        .dmem_valid_o (dmem_valid0),
        .dmem_addr_o  (dmem_addr0),
        .dmem_wdata_o (dmem_wdata0),
        .dmem_wstrb_o (dmem_wstrb0),
        .dmem_ready_i (dmem_ready0),
        .dmem_rdata_i (dmem_rdata0),

        .uart_tx_o (uart0),

        .switches_i (sw0),
        .leds_o     (led0),

        .tmem_req_o      (tmem_req0),
        .tmem_we_o       (tmem_we0),
        .tmem_addr_o     (tmem_addr0),
        .tmem_wdata_o    (tmem_wdata0),
        .tmem_wstrb_o    (tmem_wstrb0),
        .tmem_is_fetch_o (tmem_is_fetch0),

        .tmem_gnt_i    (tmem_gnt0),
        .tmem_rvalid_i (tmem_rvalid0),
        .tmem_rdata_i  (tmem_rdata0),
        .tmem_err_i    (tmem_err0),
        .tmem_err_code_i (4'd3),   // Lane 1 (A3)

        .attested_i           (attested0),

        .grant_done_i         (1'b0),   // Lane 1 (B4)

        .attest_failed_i      (1'b0),
        .last_fault_timeout_i (timeout0),
        .attest_req_o         (attest_req0),

        .dbg_pc_o    (pc0),
        .dbg_inst_o  (inst0),
        .dbg_valid_o (valid0),
        .dbg_trap_o  (trap0)
    );


    // ============================================================
    // TILE 1
    // ============================================================

    tile_top #(
        .TILE_ID    (4'h1),
        .BUILD_ID   (32'h0000_0002),
        .IMEM_WORDS (4096),
        .DMEM_WORDS (4096),
        .HAS_UART   (1'b1)
    ) tile1 (
        .clk_i   (clk),
        .reset_i (reset),

        .imem_valid_o (imem_valid1),
        .imem_addr_o  (imem_addr1),
        .imem_wdata_o (imem_wdata1),
        .imem_wstrb_o (imem_wstrb1),
        .imem_ready_i (imem_ready1),
        .imem_rdata_i (imem_rdata1),

        .dmem_valid_o (dmem_valid1),
        .dmem_addr_o  (dmem_addr1),
        .dmem_wdata_o (dmem_wdata1),
        .dmem_wstrb_o (dmem_wstrb1),
        .dmem_ready_i (dmem_ready1),
        .dmem_rdata_i (dmem_rdata1),

        .uart_tx_o (uart1),

        .switches_i (sw1),
        .leds_o     (led1),

        .tmem_req_o      (tmem_req1),
        .tmem_we_o       (tmem_we1),
        .tmem_addr_o     (tmem_addr1),
        .tmem_wdata_o    (tmem_wdata1),
        .tmem_wstrb_o    (tmem_wstrb1),
        .tmem_is_fetch_o (tmem_is_fetch1),

        .tmem_gnt_i    (tmem_gnt1),
        .tmem_rvalid_i (tmem_rvalid1),
        .tmem_rdata_i  (tmem_rdata1),
        .tmem_err_i    (tmem_err1),
        .tmem_err_code_i (4'd3),   // Lane 1 (A3)

        .attested_i           (attested1),

        .grant_done_i         (1'b0),   // Lane 1 (B4)

        .attest_failed_i      (1'b0),
        .last_fault_timeout_i (timeout1),
        .attest_req_o         (attest_req1),

        .dbg_pc_o    (pc1),
        .dbg_inst_o  (inst1),
        .dbg_valid_o (valid1),
        .dbg_trap_o  (trap1)
    );


    // ============================================================
    // TILE 0 LOCAL MEMORY
    // ============================================================

    tile_mem_wrapper #(
        .IMEM_WORDS     (4096),
        .DMEM_WORDS     (4096),
        .IMEM_INIT_FILE (""),   // preloaded from hello_words.svh below (harness-safe; Lane 1 2026-11-07)
        .DMEM_INIT_FILE ("")
    ) memory0 (
        .clk_i   (clk),
        .reset_i (reset),

        .imem_valid_i (imem_valid0),
        .imem_addr_i  (imem_addr0),
        .imem_wdata_i (imem_wdata0),
        .imem_wstrb_i (imem_wstrb0),
        .imem_ready_o (imem_ready0),
        .imem_rdata_o (imem_rdata0),

        .dmem_valid_i (dmem_valid0),
        .dmem_addr_i  (dmem_addr0),
        .dmem_wdata_i (dmem_wdata0),
        .dmem_wstrb_i (dmem_wstrb0),
        .dmem_ready_o (dmem_ready0),
        .dmem_rdata_o (dmem_rdata0),
        .meas_rd_en_i   (1'b0),   // Lane 1 (A7): no reader in this bench
        .meas_rd_addr_i (32'b0),
        .meas_rd_data_o ()
    );


    // ============================================================
    // TILE 1 LOCAL MEMORY
    // ============================================================

    tile_mem_wrapper #(
        .IMEM_WORDS     (4096),
        .DMEM_WORDS     (4096),
        .IMEM_INIT_FILE (""),   // preloaded from hello_words.svh below (harness-safe; Lane 1 2026-11-07)
        .DMEM_INIT_FILE ("")
    ) memory1 (
        .clk_i   (clk),
        .reset_i (reset),

        .imem_valid_i (imem_valid1),
        .imem_addr_i  (imem_addr1),
        .imem_wdata_i (imem_wdata1),
        .imem_wstrb_i (imem_wstrb1),
        .imem_ready_o (imem_ready1),
        .imem_rdata_o (imem_rdata1),

        .dmem_valid_i (dmem_valid1),
        .dmem_addr_i  (dmem_addr1),
        .dmem_wdata_i (dmem_wdata1),
        .dmem_wstrb_i (dmem_wstrb1),
        .dmem_ready_o (dmem_ready1),
        .dmem_rdata_o (dmem_rdata1),
        .meas_rd_en_i   (1'b0),   // Lane 1 (A7): no reader in this bench
        .meas_rd_addr_i (32'b0),
        .meas_rd_data_o ()
    );


    // ============================================================
    // TILE 0 REMOTE MEMORY TILE
    // ============================================================

    memory_tile #(
        .TILE_ID   (4'h2),
        .MEM_WORDS (4096)
    ) remote_memory (
        .clk_i   (clk),
        .reset_i (reset),

        .tmem_req_i      (tmem_req0),
        .tmem_we_i       (tmem_we0),
        .tmem_addr_i     (tmem_addr0),
        .tmem_wdata_i    (tmem_wdata0),
        .tmem_wstrb_i    (tmem_wstrb0),
        .tmem_is_fetch_i (tmem_is_fetch0),

        .tmem_gnt_o      (tmem_gnt0),
        .tmem_rvalid_o   (tmem_rvalid0),
        .tmem_rdata_o    (tmem_rdata0),
        .tmem_err_o      (tmem_err0)
    );


    // ============================================================
    // TILE 1 HAS NO REMOTE TARGET YET
    // ============================================================

    assign tmem_gnt1    = 1'b0;
    assign tmem_rvalid1 = 1'b0;
    assign tmem_rdata1  = 32'b0;
    assign tmem_err1    = 1'b0;


    // Lane 1 2026-11-06: per-tile accounting (core transfers, adapter captures, responses), max PC, traps.
    int t2_checks = 0, t2_errors = 0;
    int t2_xfer0 = 0, t2_cap0 = 0, t2_resp0 = 0, t2_xfer1 = 0, t2_cap1 = 0, t2_resp1 = 0;
    logic [31:0] t2_max_pc0 = 0, t2_max_pc1 = 0;
    int q_x0, q_c0, q_r0, q_x1, q_c1, q_r1;
    bit t2_trap_seen0 = 0, t2_trap_seen1 = 0;
    function automatic void t2_check(input bit ok, input string name);
        t2_checks++; if (ok) $display("[PASS] %s", name); else begin t2_errors++; $display("[FAIL] %s", name); end
    endfunction
    always @(posedge clk) if (!reset) begin
        if (tile0.mem_valid && tile0.mem_ready) t2_xfer0++;
        if (tile1.mem_valid && tile1.mem_ready) t2_xfer1++;
        if (tile0.adapter_inst.state_q == 2'd0 && tile0.adapter_inst.capture) t2_cap0++;
        if (tile1.adapter_inst.state_q == 2'd0 && tile1.adapter_inst.capture) t2_cap1++;
        if (tile0.adapter_inst.mem_ready_q) t2_resp0++;
        if (tile1.adapter_inst.mem_ready_q) t2_resp1++;
        if (tile0.cpu.reg_pc > t2_max_pc0) t2_max_pc0 = tile0.cpu.reg_pc;
        if (tile1.cpu.reg_pc > t2_max_pc1) t2_max_pc1 = tile1.cpu.reg_pc;
        if (tile0.cpu.trap) t2_trap_seen0 = 1;
        if (tile1.cpu.trap) t2_trap_seen1 = 1;
    end

    // ============================================================
    // TEST
    // ============================================================

    initial begin

        clk   = 1'b0;
        reset = 1'b1;

        sw0 = 4'b0101;
        sw1 = 4'b1010;

        attested0 = 1'b1;
        attested1 = 1'b0;

        timeout0 = 1'b0;
        timeout1 = 1'b0;

        $display("");
        $display("==============================================");
        $display(" TWO TILE + MEMORY TILE INTEGRATION TEST");
        $display("==============================================");

        #200;
        reset = 1'b0;

        // --------------------------------------------------------
        // Lane 1 2026-11-06 (R1.2): run both CPUs to their end loop (PC unchanged for 1,000 cycles, at most
        // 2.5 M cycles) instead of sampling after a fixed 20 us, then reconcile per-tile transaction counts.
        // Checks (CHECKS = 9 in tb_two_programs; the 8 below + T2_TILE1_MEMTEST_VALUE):
        //   T2_TILE<k>_END_LOOP  max PC > 0x12C and the CPU reached its end loop           (k = 0, 1)
        //   T2_TILE<k>_COUNTS    core transfers = adapter captures = responses after drain (k = 0, 1)
        //   T2_TILE<k>_NO_TRAP   no CPU trap                                                 (k = 0, 1)
        //   T2_REMOTE_WRITE_OK   direct TMEM write to the memory tile: one response, no error
        //   T2_REMOTE_READ_DATA  direct TMEM read returns the written word
        // --------------------------------------------------------
        begin : run_cpus
            automatic int n = 0, stable0 = 0, stable1 = 0;
            automatic logic [31:0] last0 = '1, last1 = '1;
            while ((stable0 < 1000 || stable1 < 1000) && n < 2500000) begin
                @(posedge clk); n++;
                if (tile0.cpu.reg_pc == last0) stable0++; else begin stable0 = 0; last0 = tile0.cpu.reg_pc; end
                if (tile1.cpu.reg_pc == last1) stable1++; else begin stable1 = 0; last1 = tile1.cpu.reg_pc; end
            end
            repeat (20) @(posedge clk);   // drain
            $display("T2 RUN: cycles=%0d pc0=%h max0=%h pc1=%h max1=%h", n, tile0.cpu.reg_pc, t2_max_pc0, tile1.cpu.reg_pc, t2_max_pc1);
            t2_check(t2_max_pc0 > 32'h12c && stable0 >= 1000, $sformatf("T2_TILE0_END_LOOP max_pc=%h stable=%0d", t2_max_pc0, stable0));
            t2_check(t2_max_pc1 > 32'h12c && stable1 >= 1000, $sformatf("T2_TILE1_END_LOOP max_pc=%h stable=%0d", t2_max_pc1, stable1));
            // counts snapshot per tile at a quiescent instant (adapter IDLE, no ready pulse, no capture pending): tile 0 keeps
            // fetching in its end loop while tile 1 finishes memtest, so a free-running sample can catch one request in flight
            begin : quiesce
                automatic int w = 0;
                while (!(tile0.adapter_inst.state_q == 2'd0 && !tile0.adapter_inst.mem_ready_q && !tile0.adapter_inst.capture) && w < 100) begin @(negedge clk); w++; end
                q_x0 = t2_xfer0; q_c0 = t2_cap0; q_r0 = t2_resp0; w = 0;
                while (!(tile1.adapter_inst.state_q == 2'd0 && !tile1.adapter_inst.mem_ready_q && !tile1.adapter_inst.capture) && w < 100) begin @(negedge clk); w++; end
                q_x1 = t2_xfer1; q_c1 = t2_cap1; q_r1 = t2_resp1;
            end
            t2_check(q_x0 == q_c0 && q_x0 == q_r0, $sformatf("T2_TILE0_COUNTS xfers=%0d captures=%0d responses=%0d", q_x0, q_c0, q_r0));
            t2_check(q_x1 == q_c1 && q_x1 == q_r1, $sformatf("T2_TILE1_COUNTS xfers=%0d captures=%0d responses=%0d", q_x1, q_c1, q_r1));
            t2_check(!t2_trap_seen0, $sformatf("T2_TILE0_NO_TRAP trap=%0b", t2_trap_seen0));
            t2_check(!t2_trap_seen1, $sformatf("T2_TILE1_NO_TRAP trap=%0b", t2_trap_seen1));
        end

        // --------------------------------------------------------
        // Direct TMEM write / read to the memory tile (interface check; both CPUs are parked in their end loop).
        // --------------------------------------------------------
        begin : remote
            automatic int n; automatic bit ok_w, ok_r;
            tile0.adapter_inst.a5_external_traffic = 1'b1;   // A5 bench hook: this block drives TMEM directly
            @(negedge clk);
            force tmem_req0 = 1'b1; force tmem_we0 = 1'b1; force tmem_addr0 = 32'h2200_0000;
            force tmem_wdata0 = 32'hCAFE_BABE; force tmem_wstrb0 = 4'b1111; force tmem_is_fetch0 = 1'b0;
            n = 0; while (!tmem_gnt0 && n < 1000) begin @(negedge clk); n++; end
            @(negedge clk);
            release tmem_req0; release tmem_we0; release tmem_addr0; release tmem_wdata0; release tmem_wstrb0; release tmem_is_fetch0;
            n = 0; while (!tmem_rvalid0 && n < 1000) begin @(negedge clk); n++; end
            ok_w = tmem_rvalid0 && !tmem_err0;
            t2_check(ok_w, $sformatf("T2_REMOTE_WRITE_OK rvalid=%0b err=%0b", tmem_rvalid0, tmem_err0));
            @(negedge clk);
            force tmem_req0 = 1'b1; force tmem_we0 = 1'b0; force tmem_addr0 = 32'h2200_0000;
            force tmem_wdata0 = 32'b0; force tmem_wstrb0 = 4'b0000; force tmem_is_fetch0 = 1'b0;   // data read (not a fetch)
            n = 0; while (!tmem_gnt0 && n < 1000) begin @(negedge clk); n++; end
            @(negedge clk);
            release tmem_req0; release tmem_we0; release tmem_addr0; release tmem_wdata0; release tmem_wstrb0; release tmem_is_fetch0;
            n = 0; while (!tmem_rvalid0 && n < 1000) begin @(negedge clk); n++; end
            ok_r = tmem_rvalid0 && !tmem_err0 && tmem_rdata0 == 32'hCAFE_BABE;
            t2_check(ok_r, $sformatf("T2_REMOTE_READ_DATA data=%h err=%0b", tmem_rdata0, tmem_err0));
            repeat (4) @(negedge clk); tile0.adapter_inst.a5_external_traffic = 1'b0;
        end
        t2_check(memory1.dmem_inst.mem[0] == 32'h600D_0011, $sformatf("T2_TILE1_MEMTEST_VALUE result=%h", memory1.dmem_inst.mem[0]));

        $display("CHECKS : %0d", t2_checks);
        $display("ERRORS : %0d", t2_errors);
        $display("RESULT : %s", t2_errors == 0 && t2_checks == 9 ? "PASS" : "FAIL");
        #100;
        $finish;
    end

    // A1 bounded simulation watchdog. This also bounds the testbench waits
    // when simulation time is advancing normally.
    initial begin
        #60ms;
        $display("FAIL: timeout in tb_two_tiles");
        $display("RESULT : FAIL");
        $fflush;
        $finish;   // Lane 1: $fatal does not end an xsim -R run
    end

endmodule